  const fmt = (n) => '$' + n.toLocaleString('en-US');
  const toggle = document.querySelector('.billing-toggle');
  const status = document.getElementById('pricing-status');
  const getPeriod = () => toggle.querySelector('input:checked').value;

  function billedText(plan, period) {
    if (plan.monthly === 0) return 'Free forever';                  // Q3
    return period === 'annual' ? `Billed ${fmt(plan.billedYearly)} yearly` : ''; // Q4: line keeps its height
