  toggle.addEventListener('change', () => {
    const period = getPeriod();
    render(period);
    status.textContent = period === 'annual'
      ? 'Showing annual prices, billed yearly.'
      : 'Showing monthly prices, billed monthly.';
  });

  // Browsers can restore radio state on back/forward navigation, so re-sync
  // the prices silently.
  render(getPeriod());
