      const plan = PLANS[btn.dataset.plan];

      btn.setAttribute('aria-disabled', 'true');
      label.textContent = 'Starting…';
      status.textContent = `Starting your ${plan.name} plan…`;

      try {
        await startSignup(btn.dataset.plan, getPeriod());
        // Production: window.location.assign(url) and leave the button busy.
      } catch {
        status.textContent = 'Something went wrong. Please try again.';
      } finally {
        btn.removeAttribute('aria-disabled');   // demo only: restore the button
        label.textContent = idleText;
      }
    });
  });

  // Stub. Replace with the real signup/checkout call (Q10).
